using System.Globalization; var veiculos=new Dictionary<string,DateTime>(StringComparer.OrdinalIgnoreCase); const decimal precoInicial=5m,precoHora=3m; while(true){Console.WriteLine("1-Entrar 2-Sair 3-Listar 0-Encerrar");var opcao=Console.ReadLine();if(opcao=="0")break;switch(opcao){case "1":Console.Write("Placa: ");var placa=Console.ReadLine()?.Trim();if(!string.IsNullOrEmpty(placa)&&veiculos.TryAdd(placa,DateTime.Now))Console.WriteLine("Entrada registrada");else Console.WriteLine("Placa inválida ou já cadastrada");break;case "2":Console.Write("Placa: ");var saida=Console.ReadLine()??"";if(veiculos.Remove(saida,out var entrada)){var horas=Math.Max(1,(int)Math.Ceiling((DateTime.Now-entrada).TotalHours));Console.WriteLine($"Cobrar: {precoInicial+horas*precoHora:C} ({horas}h)");}else Console.WriteLine("Não encontrada");break;case "3":foreach(var item in veiculos)Console.WriteLine($"{item.Key} - {item.Value:g}");break;}}
